import json, re
from bs4 import BeautifulSoup
def добути(html):
 суп=BeautifulSoup(html,'html.parser')
 ф={'назва':суп.select_one('.product').get_text()}
 ф['ознака']=bool(re.search('вовна',суп.get_text()))
 return ф
def записати(ф):
 р={'назва':ф['назва']}
 json.dump([р],open('catalog.json','w'))
записати(добути(html))

